fn env_flag_enabled(name: &str) -> bool {
    env_trimmed(name)
        .and_then(|value| parse_env_bool_legacy_compatible(&value))
        .unwrap_or(false)
}

fn reconnect_correction_diagnostics_format_from_env() -> Option<ReconnectCorrectionDiagnosticsFormat>
{
    if env_flag_enabled("SYNCPLAY_CLIENT_LOG_RECONNECT_CORRECTION_DIAGNOSTICS_JSON") {
        return Some(ReconnectCorrectionDiagnosticsFormat::Json);
    }
    if env_flag_enabled("SYNCPLAY_CLIENT_LOG_RECONNECT_CORRECTION_DIAGNOSTICS") {
        return Some(ReconnectCorrectionDiagnosticsFormat::Text);
    }
    None
}

fn reconnect_correction_diagnostics_alert_thresholds_from_env()
-> ReconnectCorrectionDiagnosticsAlertThresholds {
    ReconnectCorrectionDiagnosticsAlertThresholds {
        action_failures_delta: env_u32(
            "SYNCPLAY_CLIENT_RECONNECT_CORRECTION_ALERT_ACTION_FAILURES_DELTA_THRESHOLD",
        )
        .map(u64::from),
        retry_exhaustions_delta: env_u32(
            "SYNCPLAY_CLIENT_RECONNECT_CORRECTION_ALERT_RETRY_EXHAUSTIONS_DELTA_THRESHOLD",
        )
        .map(u64::from),
        disables_after_repeated_mismatches_delta: env_u32(
            "SYNCPLAY_CLIENT_RECONNECT_CORRECTION_ALERT_DISABLES_DELTA_THRESHOLD",
        )
        .map(u64::from),
        consecutive_mismatch_cycles: env_u32(
            "SYNCPLAY_CLIENT_RECONNECT_CORRECTION_ALERT_CONSECUTIVE_MISMATCH_CYCLES_THRESHOLD",
        ),
        consecutive_retry_exhaustions: env_u32(
            "SYNCPLAY_CLIENT_RECONNECT_CORRECTION_ALERT_CONSECUTIVE_RETRY_EXHAUSTIONS_THRESHOLD",
        ),
    }
}

fn client_loop_diagnostics_config_from_env() -> ClientLoopDiagnosticsConfig {
    ClientLoopDiagnosticsConfig {
        log_player_telemetry: env_flag_enabled("SYNCPLAY_CLIENT_LOG_PLAYER_TELEMETRY"),
        log_player_drift: env_flag_enabled("SYNCPLAY_CLIENT_LOG_PLAYER_DRIFT_DIAGNOSTICS"),
        reconnect_correction_diagnostics_format: reconnect_correction_diagnostics_format_from_env(),
        reconnect_correction_diagnostics_alert_thresholds:
            reconnect_correction_diagnostics_alert_thresholds_from_env(),
    }
}

fn apply_legacy_client_arg_diagnostics_overrides(
    mut config: ClientLoopDiagnosticsConfig,
    legacy_overrides: Option<&LegacyClientArgOverrides>,
) -> ClientLoopDiagnosticsConfig {
    if legacy_overrides.is_some_and(|overrides| overrides.debug_requested) {
        config.log_player_telemetry = true;
        config.log_player_drift = true;
        if config.reconnect_correction_diagnostics_format.is_none() {
            config.reconnect_correction_diagnostics_format =
                Some(ReconnectCorrectionDiagnosticsFormat::Text);
        }
    }
    config
}

fn client_loop_diagnostics_config(
    legacy_overrides: Option<&LegacyClientArgOverrides>,
) -> ClientLoopDiagnosticsConfig {
    apply_legacy_client_arg_diagnostics_overrides(
        client_loop_diagnostics_config_from_env(),
        legacy_overrides,
    )
}

fn managed_mpv_launch_env_config_from_env() -> ManagedMpvLaunchEnvConfig {
    ManagedMpvLaunchEnvConfig {
        enabled: env_flag_enabled("SYNCPLAY_CLIENT_MPV_MANAGED_LAUNCH"),
        mpv_bin: env_trimmed("SYNCPLAY_CLIENT_MPV_MANAGED_BIN").map(PathBuf::from),
        media_file: env_trimmed("SYNCPLAY_CLIENT_MPV_MANAGED_MEDIA").map(PathBuf::from),
        extra_args: Vec::new(),
        ipc_path: env_trimmed("SYNCPLAY_CLIENT_MPV_MANAGED_IPC_PATH"),
        connect_timeout_ms: env_u32("SYNCPLAY_CLIENT_MPV_MANAGED_CONNECT_TIMEOUT_MS"),
        connect_poll_interval_ms: env_u32("SYNCPLAY_CLIENT_MPV_MANAGED_CONNECT_POLL_INTERVAL_MS"),
    }
}

fn env_trimmed(name: &str) -> Option<String> {
    env::var(name).ok().and_then(|value| {
        let trimmed = value.trim();
        if trimmed.is_empty() {
            None
        } else {
            Some(trimmed.to_owned())
        }
    })
}

fn env_flag_override(name: &str) -> Option<bool> {
    env_trimmed(name).and_then(|value| parse_env_bool_legacy_compatible(&value))
}

fn parse_env_bool_legacy_compatible(value: &str) -> Option<bool> {
    let normalized = value.trim();
    if normalized.is_empty() {
        return None;
    }
    if normalized == "1"
        || normalized.eq_ignore_ascii_case("true")
        || normalized.eq_ignore_ascii_case("yes")
        || normalized.eq_ignore_ascii_case("on")
    {
        return Some(true);
    }
    if normalized == "0"
        || normalized.eq_ignore_ascii_case("false")
        || normalized.eq_ignore_ascii_case("no")
        || normalized.eq_ignore_ascii_case("off")
    {
        return Some(false);
    }
    None
}

fn parse_env_port_legacy_compatible(value: &str) -> Option<u16> {
    let port = value.trim().parse::<u16>().ok()?;
    (port > 0).then_some(port)
}

fn env_port(name: &str) -> Option<u16> {
    env_trimmed(name).and_then(|value| parse_env_port_legacy_compatible(&value))
}

fn parse_env_string_list_legacy_compatible(value: &str) -> Option<Vec<String>> {
    let values: Vec<String> = value
        .split([',', ';', '\n', '\r'])
        .map(str::trim)
        .filter(|entry| !entry.is_empty())
        .map(ToOwned::to_owned)
        .collect();
    if values.is_empty() {
        None
    } else {
        Some(values)
    }
}

fn env_string_list(name: &str) -> Option<Vec<String>> {
    env_trimmed(name).and_then(|value| parse_env_string_list_legacy_compatible(&value))
}

fn syncplay_config_names_legacy_compatible() -> [&'static str; 2] {
    [".syncplay", "syncplay.ini"]
}

fn syncplay_cli_config_path_override() -> Option<PathBuf> {
    env_trimmed("SYNCPLAY_CLIENT_CONFIG_PATH").map(PathBuf::from)
}

fn syncplay_cli_legacy_gui_qsettings_root_override() -> Option<PathBuf> {
    env_trimmed("SYNCPLAY_CLIENT_LEGACY_QSETTINGS_ROOT").map(PathBuf::from)
}

fn default_syncplay_cli_config_root_legacy_compatible() -> Option<PathBuf> {
    if cfg!(windows) {
        return env_trimmed("APPDATA").map(PathBuf::from);
    }
    if let Some(xdg_config_home) = env_trimmed("XDG_CONFIG_HOME") {
        return Some(PathBuf::from(xdg_config_home));
    }
    env_trimmed("HOME").map(|home| PathBuf::from(home).join(".config"))
}

fn resolve_syncplay_cli_config_path_legacy_compatible() -> Option<PathBuf> {
    if let Some(path) = syncplay_cli_config_path_override() {
        return Some(path);
    }
    if let Ok(cwd) = std::env::current_dir() {
        for name in syncplay_config_names_legacy_compatible() {
            let candidate = cwd.join(name);
            if candidate.is_file() {
                return Some(candidate);
            }
        }
    }
    let root = default_syncplay_cli_config_root_legacy_compatible()?;
    for name in syncplay_config_names_legacy_compatible() {
        let candidate = root.join(name);
        if candidate.is_file() {
            return Some(candidate);
        }
    }
    Some(root.join("syncplay.ini"))
}

