fn timeout_ms_from_stored_client_setting_legacy_compatible(
    value: Option<i64>,
    default_ms: u64,
) -> u64 {
    value
        .and_then(|seconds| {
            let seconds = u64::try_from(seconds).ok()?;
            seconds.checked_mul(1_000)
        })
        .unwrap_or(default_ms)
}

fn legacy_syncplay_ui_settings_from_stored_settings(
    settings: Option<&StoredClientSettingsMvp>,
) -> LegacySyncplayUiSettings {
    let mut resolved = LegacySyncplayUiSettings::default();
    let Some(settings) = settings else {
        return resolved;
    };

    if let Some(show_osd) = settings.show_osd {
        resolved.show_osd = show_osd;
    }
    if let Some(chat_output_enabled) = settings.chat_output_enabled {
        resolved.chat_output_enabled = chat_output_enabled;
    }
    if let Some(chat_input_enabled) = settings.chat_input_enabled {
        resolved.chat_input_enabled = chat_input_enabled;
    }
    if let Some(chat_input_font_underline) = settings.chat_input_font_underline {
        resolved.chat_input_font_underline = chat_input_font_underline;
    }
    if let Some(chat_input_font_family) = settings
        .chat_input_font_family
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        resolved.chat_input_font_family = chat_input_font_family.to_owned();
    }
    if let Some(chat_input_relative_font_size) = settings
        .chat_input_relative_font_size
        .filter(|value| *value > 0)
    {
        resolved.chat_input_relative_font_size = chat_input_relative_font_size;
    }
    if let Some(chat_input_font_weight) = settings.chat_input_font_weight {
        resolved.chat_input_font_weight = chat_input_font_weight;
    }
    if let Some(chat_input_font_color) = settings
        .chat_input_font_color
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        resolved.chat_input_font_color = chat_input_font_color.to_owned();
    }
    if let Some(chat_input_position) = settings
        .chat_input_position
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        resolved.chat_input_position = chat_input_position.to_owned();
    }
    if let Some(chat_direct_input) = settings.chat_direct_input {
        resolved.chat_direct_input = chat_direct_input;
    }
    if let Some(chat_output_font_underline) = settings.chat_output_font_underline {
        resolved.chat_output_font_underline = chat_output_font_underline;
    }
    if let Some(chat_output_font_family) = settings
        .chat_output_font_family
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        resolved.chat_output_font_family = chat_output_font_family.to_owned();
    }
    if let Some(chat_output_relative_font_size) = settings
        .chat_output_relative_font_size
        .filter(|value| *value > 0)
    {
        resolved.chat_output_relative_font_size = chat_output_relative_font_size;
    }
    if let Some(chat_output_font_weight) = settings.chat_output_font_weight {
        resolved.chat_output_font_weight = chat_output_font_weight;
    }
    if let Some(chat_output_mode) = settings
        .chat_output_mode
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        resolved.chat_output_mode = chat_output_mode.to_owned();
    }
    if let Some(chat_max_lines) = settings.chat_max_lines.filter(|value| *value > 0) {
        resolved.chat_max_lines = chat_max_lines;
    }
    if let Some(chat_top_margin) = settings.chat_top_margin.filter(|value| *value >= 0) {
        resolved.chat_top_margin = chat_top_margin;
    }
    if let Some(chat_left_margin) = settings.chat_left_margin.filter(|value| *value >= 0) {
        resolved.chat_left_margin = chat_left_margin;
    }
    if let Some(chat_bottom_margin) = settings.chat_bottom_margin.filter(|value| *value >= 0) {
        resolved.chat_bottom_margin = chat_bottom_margin;
    }
    if let Some(chat_move_osd) = settings.chat_move_osd {
        resolved.chat_move_osd = chat_move_osd;
    }
    if let Some(chat_osd_margin) = settings.chat_osd_margin.filter(|value| *value >= 0) {
        resolved.chat_osd_margin = chat_osd_margin;
    }
    resolved.notification_timeout_ms = timeout_ms_from_stored_client_setting_legacy_compatible(
        settings.notification_timeout_seconds,
        resolved.notification_timeout_ms,
    );
    resolved.alert_timeout_ms = timeout_ms_from_stored_client_setting_legacy_compatible(
        settings.alert_timeout_seconds,
        resolved.alert_timeout_ms,
    );
    resolved.chat_timeout_ms = timeout_ms_from_stored_client_setting_legacy_compatible(
        settings.chat_timeout_seconds,
        resolved.chat_timeout_ms,
    );
    resolved
}

fn legacy_syncplayintf_script_candidate_paths_legacy_compatible() -> Vec<PathBuf> {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    vec![
        manifest_dir.join("../../resources/syncplayintf.lua"),
        manifest_dir
            .join("../../.interop-cache/syncplay-legacy/syncplay/resources/syncplayintf.lua"),
        manifest_dir.join("../../../syncplay/syncplay/resources/syncplayintf.lua"),
    ]
}

const LEGACY_SYNCPLAYINTF_CHAT_INPUT_BRIDGE_MARKER: &str = "-- syncplay-rust-chat-input-bridge";

fn legacy_syncplayintf_chat_input_bridge_source_legacy_compatible() -> &'static str {
    r#"
-- syncplay-rust-chat-input-bridge
local syncplay_rust_original_handle_enter = handle_enter
function handle_enter()
    if repl_active and line ~= '' then
        local syncplay_rust_chat_line = line
        if opts['backslashSubstituteCharacter'] ~= nil then
            syncplay_rust_chat_line = string.gsub(syncplay_rust_chat_line, opts['backslashSubstituteCharacter'], "\\")
        end
        mp.commandv("script-message", "syncplayintf-chat", syncplay_rust_chat_line)
    end
    syncplay_rust_original_handle_enter()
end
"#
}

fn legacy_syncplayintf_script_source_with_chat_input_bridge_legacy_compatible(
    source: &str,
) -> String {
    if source.contains(LEGACY_SYNCPLAYINTF_CHAT_INPUT_BRIDGE_MARKER) {
        return source.to_owned();
    }

    let mut patched = source.to_owned();
    if !patched.ends_with('\n') {
        patched.push('\n');
    }
    patched.push_str(legacy_syncplayintf_chat_input_bridge_source_legacy_compatible());
    patched
}

fn prepare_legacy_syncplayintf_script_path_legacy_compatible(
    source_path: &Path,
) -> anyhow::Result<PathBuf> {
    let source = fs::read_to_string(source_path).map_err(|error| {
        anyhow!(
            "failed to read syncplayintf.lua from '{}': {error}",
            source_path.display()
        )
    })?;
    if source.contains(LEGACY_SYNCPLAYINTF_CHAT_INPUT_BRIDGE_MARKER) {
        return Ok(source_path.to_path_buf());
    }

    let patched =
        legacy_syncplayintf_script_source_with_chat_input_bridge_legacy_compatible(&source);
    let target_path = std::env::temp_dir().join(format!(
        "syncplay-rust-syncplayintf-{}.lua",
        std::process::id()
    ));
    fs::write(&target_path, patched).map_err(|error| {
        anyhow!(
            "failed to write patched syncplayintf.lua to '{}': {error}",
            target_path.display()
        )
    })?;
    Ok(target_path)
}

fn find_legacy_syncplayintf_script_path_legacy_compatible() -> Option<PathBuf> {
    let source_path = legacy_syncplayintf_script_candidate_paths_legacy_compatible()
        .into_iter()
        .find(|candidate| candidate.is_file())?;
    Some(
        prepare_legacy_syncplayintf_script_path_legacy_compatible(&source_path)
            .unwrap_or(source_path),
    )
}

fn apply_legacy_syncplay_ui_settings_to_mpv_adapter_legacy_compatible(
    player: &mut MpvAdapter,
    settings: Option<&StoredClientSettingsMvp>,
) -> anyhow::Result<()> {
    let resolved = legacy_syncplay_ui_settings_from_stored_settings(settings);
    player
        .configure_legacy_syncplay_ui_settings(resolved.clone())
        .map_err(|error| anyhow!("failed to configure mpv OSD/chat settings: {error}"))?;

    if (resolved.chat_output_enabled || resolved.chat_input_enabled)
        && let Some(script_path) = find_legacy_syncplayintf_script_path_legacy_compatible()
        && let Err(error) = player.load_legacy_syncplayintf_script(&script_path)
    {
        eprintln!(
            "warning: failed to load legacy mpv syncplayintf.lua from '{}' via JSON IPC: {}",
            script_path.display(),
            error
        );
    }

    Ok(())
}

fn apply_stored_media_search_startup_file_fallback_if_missing_legacy_compatible(
    overrides: &mut LegacyClientArgOverrides,
    settings: Option<&StoredClientSettingsMvp>,
) {
    let resolution = resolve_legacy_startup_file_with_media_search_fallback_legacy_compatible(
        overrides.file.as_deref(),
        settings,
    );
    for line in resolution.warning_lines {
        eprintln!("{line}");
    }
    overrides.file = resolution.file;
}

fn resolve_legacy_startup_file_with_media_search_fallback_legacy_compatible(
    requested_file: Option<&str>,
    settings: Option<&StoredClientSettingsMvp>,
) -> LegacyStartupMediaSearchResolution {
    let Some(requested_file) = requested_file
        .map(str::trim)
        .filter(|file| !file.is_empty())
    else {
        return LegacyStartupMediaSearchResolution::default();
    };

    let requested_path = Path::new(requested_file);
    if requested_file.contains("://")
        || requested_file.starts_with("magnet:")
        || requested_path.is_file()
        || requested_path.is_absolute()
    {
        return LegacyStartupMediaSearchResolution {
            file: Some(requested_file.to_owned()),
            warning_lines: Vec::new(),
        };
    }

    let Some(settings) = settings else {
        return LegacyStartupMediaSearchResolution {
            file: Some(requested_file.to_owned()),
            warning_lines: Vec::new(),
        };
    };
    let Some(media_directories) = settings.media_search_directories.as_ref() else {
        return LegacyStartupMediaSearchResolution {
            file: Some(requested_file.to_owned()),
            warning_lines: Vec::new(),
        };
    };

    let simple_file_name = requested_path
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| *name == requested_file);

    let first_file_timeout_seconds = settings
        .folder_search_first_file_timeout_seconds
        .unwrap_or(LEGACY_FOLDER_SEARCH_FIRST_FILE_TIMEOUT_SECONDS_DEFAULT);
    let folder_timeout_seconds = settings
        .folder_search_timeout_seconds
        .unwrap_or(LEGACY_FOLDER_SEARCH_TIMEOUT_SECONDS_DEFAULT);
    let warning_threshold_seconds = settings
        .folder_search_warning_threshold_seconds
        .unwrap_or(LEGACY_FOLDER_SEARCH_WARNING_THRESHOLD_SECONDS_DEFAULT);
    let warning_repeat_interval_seconds = settings
        .folder_search_double_check_interval_seconds
        .unwrap_or(LEGACY_FOLDER_SEARCH_DOUBLE_CHECK_INTERVAL_SECONDS_DEFAULT);

    let mut warning_lines = Vec::new();
    for directory in media_directories
        .iter()
        .map(String::as_str)
        .filter(|directory| !directory.trim().is_empty())
    {
        let directory_path = Path::new(directory);
        if !directory_path.is_dir() {
            warning_lines.push(format!(
                "warning: legacy mediaSearchDirectories ignored missing media directory '{directory}'",
            ));
            continue;
        }

        let direct_candidate = directory_path.join(requested_file);
        if direct_candidate.is_file() {
            return LegacyStartupMediaSearchResolution {
                file: Some(direct_candidate.to_string_lossy().into_owned()),
                warning_lines,
            };
        }

        let Some(simple_file_name) = simple_file_name else {
            continue;
        };

        if first_file_timeout_seconds <= 0.0 {
            warning_lines.push(format!(
                "warning: legacy mediaSearchDirectories skipped recursive startup-file search in '{directory}' because folderSearchFirstFileTimeout is 0",
            ));
            continue;
        }

        let first_probe_started = Instant::now();
        if std::fs::read_dir(directory_path).is_err() {
            warning_lines.push(format!(
                "warning: legacy mediaSearchDirectories could not access media directory '{directory}'",
            ));
            continue;
        }
        if first_probe_started.elapsed().as_secs_f64() > first_file_timeout_seconds {
            warning_lines.push(format!(
                "warning: legacy mediaSearchDirectories skipped recursive startup-file search in '{directory}' because folderSearchFirstFileTimeout was exceeded",
            ));
            continue;
        }

        if folder_timeout_seconds <= 0.0 {
            warning_lines.push(format!(
                "warning: legacy mediaSearchDirectories aborted recursive startup-file search in '{directory}' because folderSearchTimeout is 0",
            ));
            continue;
        }

        if let Some(found_path) = search_media_directories_for_startup_file_name_legacy_compatible(
            directory_path,
            simple_file_name,
            folder_timeout_seconds,
            warning_threshold_seconds,
            warning_repeat_interval_seconds,
            &mut warning_lines,
        ) {
            return LegacyStartupMediaSearchResolution {
                file: Some(found_path.to_string_lossy().into_owned()),
                warning_lines,
            };
        }
    }

    LegacyStartupMediaSearchResolution {
        file: Some(requested_file.to_owned()),
        warning_lines,
    }
}

fn search_media_directories_for_startup_file_name_legacy_compatible(
    root_directory: &Path,
    target_file_name: &str,
    folder_timeout_seconds: f64,
    warning_threshold_seconds: f64,
    warning_repeat_interval_seconds: f64,
    warning_lines: &mut Vec<String>,
) -> Option<PathBuf> {
    let search_started = Instant::now();
    let mut last_warning_elapsed_seconds = None::<f64>;
    let mut scanned_file_count = 0usize;
    let mut pending_directories = vec![root_directory.to_path_buf()];
    let warning_repeat_interval_seconds = warning_repeat_interval_seconds.max(1.0);

    while let Some(directory) = pending_directories.pop() {
        if search_started.elapsed().as_secs_f64() > folder_timeout_seconds {
            warning_lines.push(format!(
                "warning: legacy mediaSearchDirectories aborted recursive startup-file search in '{}' after scanning {} file(s) because folderSearchTimeout was reached",
                root_directory.display(),
                scanned_file_count
            ));
            return None;
        }

        let Ok(entries) = std::fs::read_dir(&directory) else {
            continue;
        };
        for entry in entries {
            let elapsed_seconds = search_started.elapsed().as_secs_f64();
            if elapsed_seconds > folder_timeout_seconds {
                warning_lines.push(format!(
                    "warning: legacy mediaSearchDirectories aborted recursive startup-file search in '{}' after scanning {} file(s) because folderSearchTimeout was reached",
                    root_directory.display(),
                    scanned_file_count
                ));
                return None;
            }
            if elapsed_seconds > warning_threshold_seconds
                && last_warning_elapsed_seconds
                    .is_none_or(|last| elapsed_seconds - last >= warning_repeat_interval_seconds)
            {
                warning_lines.push(format!(
                    "warning: legacy mediaSearchDirectories has scanned {} file(s) in '{}' for {} second(s) while resolving the startup file",
                    scanned_file_count,
                    root_directory.display(),
                    elapsed_seconds.floor() as u64
                ));
                last_warning_elapsed_seconds = Some(elapsed_seconds);
            }

            let Ok(entry) = entry else {
                continue;
            };
            let Ok(file_type) = entry.file_type() else {
                continue;
            };
            if file_type.is_dir() {
                pending_directories.push(entry.path());
                continue;
            }
            if !file_type.is_file() {
                continue;
            }

            scanned_file_count = scanned_file_count.saturating_add(1);
            let file_name = entry.file_name();
            if file_name
                .to_str()
                .is_some_and(|name| name == target_file_name)
            {
                return Some(entry.path());
            }
        }
    }

    None
}

fn apply_stored_legacy_startup_player_defaults_if_arg_absent(
    overrides: &mut LegacyClientArgOverrides,
    settings: &StoredClientSettingsMvp,
) {
    if overrides.player_path.is_none()
        && let Some(player_path) = settings.player_path.as_deref()
        && !player_path.is_empty()
    {
        overrides.player_path = Some(player_path.to_owned());
    }
    if let Some(player_path) = overrides.player_path.as_deref()
        && let Some(per_player_arguments) = settings.per_player_arguments.as_ref()
        && let Some(args) = lookup_stored_per_player_arguments_for_player_path_legacy_compatible(
            per_player_arguments,
            player_path,
        )
    {
        if overrides.player_args.is_empty() {
            overrides.player_args = args.clone();
        } else {
            overrides.player_args.extend(args.iter().cloned());
        }
    }
}

fn lookup_stored_per_player_arguments_for_player_path_legacy_compatible<'a>(
    per_player_arguments: &'a BTreeMap<String, Vec<String>>,
    player_path: &str,
) -> Option<&'a Vec<String>> {
    if let Some(args) = per_player_arguments.get(player_path) {
        return Some(args);
    }
    let normalized_player_path =
        normalize_player_path_for_stored_per_player_arguments_lookup_legacy_compatible(
            player_path,
        )?;
    per_player_arguments
        .iter()
        .find_map(|(stored_player_path, args)| {
            let normalized_stored_player_path =
                normalize_player_path_for_stored_per_player_arguments_lookup_legacy_compatible(
                    stored_player_path,
                )?;
            (normalized_stored_player_path == normalized_player_path).then_some(args)
        })
}

fn normalize_player_path_for_stored_per_player_arguments_lookup_legacy_compatible(
    player_path: &str,
) -> Option<String> {
    let trimmed = player_path.trim();
    if trimmed.is_empty() {
        return None;
    }
    let slash_normalized = trimmed.replace('\\', "/");
    if looks_like_windows_player_path_legacy_compatible(trimmed) {
        return Some(slash_normalized.to_ascii_lowercase());
    }
    Some(slash_normalized)
}

fn looks_like_windows_player_path_legacy_compatible(path: &str) -> bool {
    let bytes = path.as_bytes();
    if bytes.len() >= 2 && bytes[1] == b':' && bytes[0].is_ascii_alphabetic() {
        return true;
    }
    path.starts_with("\\\\") || path.starts_with("//") || path.contains('\\')
}

