fn env_u32(name: &str) -> Option<u32> {
    env::var(name)
        .ok()
        .and_then(|value| value.trim().parse().ok())
}

fn env_usize(name: &str) -> Option<usize> {
    env::var(name)
        .ok()
        .and_then(|value| value.trim().parse().ok())
}

fn parse_env_non_negative_f64_legacy_compatible(value: &str) -> Option<f64> {
    let parsed = value.trim().parse::<f64>().ok()?;
    (parsed.is_finite() && parsed >= 0.0).then_some(parsed)
}

fn env_non_negative_f64(name: &str) -> Option<f64> {
    env_trimmed(name).and_then(|value| parse_env_non_negative_f64_legacy_compatible(&value))
}

fn env_privacy_mode(name: &str) -> Option<PrivacyMode> {
    env_trimmed(name).and_then(|value| PrivacyMode::from_legacy_name(value.as_str()))
}

fn normalize_controlled_room_input(room: String) -> (String, Option<String>) {
    shared_normalize_controlled_room_input_legacy_compatible(room)
}

fn spawn_local_input_receiver_legacy_compatible() -> UnboundedReceiver<String> {
    let (sender, receiver) = unbounded_channel::<String>();
    std::thread::spawn(move || {
        use std::io::BufRead;

        let stdin = std::io::stdin();
        for line in stdin.lock().lines() {
            match line {
                Ok(line) => {
                    if sender.send(line).is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });

    receiver
}

async fn recv_local_input_line(
    local_input_rx: &mut Option<&mut UnboundedReceiver<String>>,
) -> Option<String> {
    match local_input_rx {
        Some(receiver) => receiver.recv().await,
        None => std::future::pending::<Option<String>>().await,
    }
}

fn build_client_loop_config_from_env() -> ClientLoopConfig {
    let room = env_trimmed("SYNCPLAY_CLIENT_ROOM").unwrap_or_else(|| "cli-demo".to_owned());
    let (room, controlled_room_password_override) = normalize_controlled_room_input(room);

    ClientLoopConfig {
        host: env_trimmed("SYNCPLAY_CLIENT_HOST").unwrap_or_else(|| "127.0.0.1".to_owned()),
        port: env_port("SYNCPLAY_CLIENT_PORT").unwrap_or(8999),
        server_password: env_trimmed("SYNCPLAY_CLIENT_SERVER_PASSWORD"),
        username: env_trimmed("SYNCPLAY_CLIENT_USERNAME")
            .or_else(|| env_trimmed("SYNCPLAY_CLIENT_NAME"))
            .unwrap_or_else(|| "cli-user".to_owned()),
        room,
        version: env_trimmed("SYNCPLAY_CLIENT_VERSION").unwrap_or_else(|| "1.2.255".to_owned()),
        max_retries: env_u32("SYNCPLAY_CLIENT_MAX_RETRIES").unwrap_or(3),
        max_connected_runtime_seconds: env_non_negative_f64(
            "SYNCPLAY_CLIENT_MAX_CONNECTED_RUNTIME_SECONDS",
        )
        .unwrap_or(10.0),
        readiness_supported_override: env_flag_override("SYNCPLAY_CLIENT_READINESS_SUPPORTED"),
        local_can_control_override: env_flag_override("SYNCPLAY_CLIENT_CAN_CONTROL"),
        is_playing_music_override: env_flag_override("SYNCPLAY_CLIENT_IS_PLAYING_MUSIC"),
        recently_advanced_override: env_flag_override("SYNCPLAY_CLIENT_RECENTLY_ADVANCED"),
        autoplay_enabled: env_flag_enabled("SYNCPLAY_CLIENT_AUTOPLAY"),
        autoplay_require_same_filenames: env_flag_enabled(
            "SYNCPLAY_CLIENT_AUTOPLAY_REQUIRE_SAME_FILENAMES",
        ),
        ready_at_start_override: env_flag_override("SYNCPLAY_CLIENT_READY_AT_START"),
        shared_playlists_enabled_override: env_flag_override(
            "SYNCPLAY_CLIENT_SHARED_PLAYLIST_ENABLED",
        ),
        pause_on_leave_override: env_flag_override("SYNCPLAY_CLIENT_PAUSE_ON_LEAVE"),
        loop_at_end_of_playlist_override: env_flag_override(
            "SYNCPLAY_CLIENT_LOOP_AT_END_OF_PLAYLIST",
        ),
        loop_single_files_override: env_flag_override("SYNCPLAY_CLIENT_LOOP_SINGLE_FILES"),
        only_switch_to_trusted_domains_override: env_flag_override(
            "SYNCPLAY_CLIENT_ONLY_SWITCH_TO_TRUSTED_DOMAINS",
        ),
        trusted_domains_override: env_string_list("SYNCPLAY_CLIENT_TRUSTED_DOMAINS"),
        rewind_on_desync_override: env_flag_override("SYNCPLAY_CLIENT_REWIND_ON_DESYNC"),
        fastforward_on_desync_override: env_flag_override("SYNCPLAY_CLIENT_FASTFORWARD_ON_DESYNC"),
        slow_on_desync_override: env_flag_override("SYNCPLAY_CLIENT_SLOW_ON_DESYNC"),
        dont_slow_down_with_me_override: env_flag_override(
            "SYNCPLAY_CLIENT_DONT_SLOW_DOWN_WITH_ME",
        ),
        rewind_threshold_seconds_override: env_non_negative_f64(
            "SYNCPLAY_CLIENT_REWIND_THRESHOLD_SECONDS",
        ),
        fastforward_threshold_seconds_override: env_non_negative_f64(
            "SYNCPLAY_CLIENT_FASTFORWARD_THRESHOLD_SECONDS",
        ),
        slowdown_threshold_seconds_override: env_non_negative_f64(
            "SYNCPLAY_CLIENT_SLOWDOWN_THRESHOLD_SECONDS",
        ),
        unpause_action_override: env_trimmed("SYNCPLAY_CLIENT_UNPAUSE_ACTION")
            .and_then(|value| parse_unpause_action_mode_legacy_compatible(&value)),
        auto_play_threshold_override: env_trimmed("SYNCPLAY_CLIENT_AUTOPLAY_MIN_USERS")
            .and_then(|value| parse_autoplay_min_users_override_legacy_compatible(&value)),
        filename_privacy_mode: env_privacy_mode("SYNCPLAY_CLIENT_FILENAME_PRIVACY_MODE")
            .unwrap_or(PrivacyMode::SendRaw),
        filesize_privacy_mode: env_privacy_mode("SYNCPLAY_CLIENT_FILESIZE_PRIVACY_MODE")
            .unwrap_or(PrivacyMode::SendRaw),
        show_duration_notification_override: env_flag_override(
            "SYNCPLAY_CLIENT_SHOW_DURATION_NOTIFICATION",
        ),
        different_duration_threshold_seconds_override: env_non_negative_f64(
            "SYNCPLAY_CLIENT_DIFFERENT_DURATION_THRESHOLD_SECONDS",
        ),
        show_same_room_osd_override: env_flag_override("SYNCPLAY_CLIENT_SHOW_SAME_ROOM_OSD"),
        show_osd_warnings_override: env_flag_override("SYNCPLAY_CLIENT_SHOW_OSD_WARNINGS"),
        show_noncontroller_osd_override: env_flag_override(
            "SYNCPLAY_CLIENT_SHOW_NONCONTROLLER_OSD",
        ),
        show_different_room_osd_override: env_flag_override(
            "SYNCPLAY_CLIENT_SHOW_DIFFERENT_ROOM_OSD",
        ),
        controlled_room_password_override,
    }
}

#[cfg(test)]
fn create_client_runtime(
    config: &ClientLoopConfig,
) -> ClientRuntime<MpvAdapter, QueuedRuntimeControl> {
    let session = create_client_session(config);
    let mut player = create_mpv_adapter_from_env();
    apply_legacy_syncplay_ui_settings_to_mpv_adapter_legacy_compatible(&mut player, None)
        .expect("default legacy mpv OSD/chat settings should apply");
    ClientRuntime::new(session, player, QueuedRuntimeControl::default())
}

fn create_client_session(config: &ClientLoopConfig) -> ClientSession {
    let mut session = ClientSession::default();
    session.set_autoplay_enabled(config.autoplay_enabled);
    if let Some(control_password) = config.controlled_room_password_override.as_deref() {
        session.remember_control_password_for_room(&config.room, control_password);
    }
    if let Some(show_same_room_osd) = config.show_same_room_osd_override {
        session.behavior_config_mut().show_same_room_osd = show_same_room_osd;
    }
    if let Some(show_osd_warnings) = config.show_osd_warnings_override {
        session.behavior_config_mut().show_osd_warnings = show_osd_warnings;
    }
    if let Some(show_noncontroller_osd) = config.show_noncontroller_osd_override {
        session.behavior_config_mut().show_noncontroller_osd = show_noncontroller_osd;
    }
    if let Some(show_different_room_osd) = config.show_different_room_osd_override {
        session.behavior_config_mut().show_different_room_osd = show_different_room_osd;
    }
    if let Some(pause_on_leave) = config.pause_on_leave_override {
        session.behavior_config_mut().pause_on_leave = pause_on_leave;
    }
    if let Some(loop_at_end_of_playlist) = config.loop_at_end_of_playlist_override {
        session.behavior_config_mut().loop_at_end_of_playlist = loop_at_end_of_playlist;
    }
    if let Some(loop_single_files) = config.loop_single_files_override {
        session.behavior_config_mut().loop_single_files = loop_single_files;
    }
    if let Some(only_switch_to_trusted_domains) = config.only_switch_to_trusted_domains_override {
        session.behavior_config_mut().only_switch_to_trusted_domains =
            only_switch_to_trusted_domains;
    }
    if let Some(trusted_domains) = config.trusted_domains_override.as_ref() {
        session.behavior_config_mut().trusted_domains = trusted_domains.clone();
    }
    if let Some(rewind_on_desync) = config.rewind_on_desync_override {
        session.desync_config_mut().rewind_on_desync = rewind_on_desync;
    }
    if let Some(fastforward_on_desync) = config.fastforward_on_desync_override {
        session.desync_config_mut().fastforward_on_desync = fastforward_on_desync;
    }
    if let Some(slow_on_desync) = config.slow_on_desync_override {
        session.desync_config_mut().slow_on_desync = slow_on_desync;
    }
    if let Some(rewind_threshold_seconds) = config.rewind_threshold_seconds_override {
        session.desync_config_mut().rewind_threshold_seconds = rewind_threshold_seconds;
    }
    if let Some(fastforward_threshold_seconds) = config.fastforward_threshold_seconds_override {
        session.desync_config_mut().fastforward_threshold_seconds = fastforward_threshold_seconds;
    }
    if let Some(slowdown_threshold_seconds) = config.slowdown_threshold_seconds_override {
        session.desync_config_mut().slowdown_threshold_seconds = slowdown_threshold_seconds;
    }
    apply_client_behavior_overrides(&mut session, &behavior_overrides_from_env());
    {
        let readiness_config = session.readiness_autoplay_config_mut();
        readiness_config.autoplay_require_same_filenames = config.autoplay_require_same_filenames;
        if let Some(unpause_action) = config.unpause_action_override.as_ref() {
            readiness_config.unpause_action = unpause_action.clone();
        }
        if let Some(auto_play_threshold) = config.auto_play_threshold_override.as_ref() {
            readiness_config.auto_play_threshold = match auto_play_threshold {
                AutoplayThresholdOverride::Disable => None,
                AutoplayThresholdOverride::Set(value) => Some(*value),
            };
        }
        if let Some(show_duration_notification) = config.show_duration_notification_override {
            readiness_config.show_duration_notification = show_duration_notification;
        }
        if let Some(different_duration_threshold_seconds) =
            config.different_duration_threshold_seconds_override
        {
            readiness_config.different_duration_threshold_seconds =
                different_duration_threshold_seconds;
        }
        apply_readiness_autoplay_overrides(readiness_config, &readiness_overrides_from_env());
    }
    apply_chat_policy_overrides(&mut session, &chat_policy_overrides_from_env());
    session.reconnect_policy_mut().max_retries = config.max_retries;
    session
}

#[cfg(test)]
fn create_mpv_adapter_from_env() -> MpvAdapter {
    let ipc_path = env_trimmed("SYNCPLAY_CLIENT_MPV_IPC_PATH")
        .or_else(|| env_trimmed("SYNCPLAY_MPV_IPC_PATH"));
    let Some(ipc_path) = ipc_path else {
        return MpvAdapter::default();
    };

    create_mpv_adapter_from_path_or_stub(&ipc_path)
}

#[derive(Debug)]
struct ManagedMpvProcessGuard {
    child: Child,
    ipc_cleanup_path: Option<PathBuf>,
}

impl Drop for ManagedMpvProcessGuard {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        if let Some(path) = self.ipc_cleanup_path.as_ref() {
            let _ = std::fs::remove_file(path);
        }
    }
}

fn create_client_runtime_with_managed_mpv_support(
    config: &ClientLoopConfig,
    legacy_overrides: Option<&LegacyClientArgOverrides>,
    stored_settings: Option<&StoredClientSettingsMvp>,
) -> anyhow::Result<(
    ClientRuntime<MpvAdapter, QueuedRuntimeControl>,
    Option<ManagedMpvProcessGuard>,
)> {
    let session = create_client_session(config);
    let (mut player, managed_guard) =
        create_mpv_adapter_and_optional_managed_process_from_env(legacy_overrides)?;
    apply_legacy_syncplay_ui_settings_to_mpv_adapter_legacy_compatible(
        &mut player,
        stored_settings,
    )?;
    Ok((
        ClientRuntime::new(session, player, QueuedRuntimeControl::default()),
        managed_guard,
    ))
}

fn create_mpv_adapter_and_optional_managed_process_from_env(
    legacy_overrides: Option<&LegacyClientArgOverrides>,
) -> anyhow::Result<(MpvAdapter, Option<ManagedMpvProcessGuard>)> {
    let explicit_ipc_path = explicit_mpv_ipc_path_from_env();
    if let Some(ipc_path) = explicit_ipc_path {
        return Ok((create_mpv_adapter_from_path_or_stub(&ipc_path), None));
    }

    let mut managed_config = managed_mpv_launch_env_config_from_env();
    apply_legacy_client_arg_managed_mpv_overrides(&mut managed_config, legacy_overrides);
    if !managed_config.enabled {
        return Ok((MpvAdapter::default(), None));
    }

    let (adapter, guard) = spawn_managed_mpv_and_attach(managed_config)?;
    Ok((adapter, Some(guard)))
}

fn apply_legacy_client_arg_managed_mpv_overrides(
    managed_config: &mut ManagedMpvLaunchEnvConfig,
    legacy_overrides: Option<&LegacyClientArgOverrides>,
) {
    let Some(overrides) = legacy_overrides else {
        return;
    };
    let legacy_player_path = overrides.player_path.as_deref();
    let legacy_player_requests_managed_mpv =
        legacy_player_path.is_some_and(legacy_player_path_requests_managed_mpv_legacy_compatible);

    if !managed_config.enabled && legacy_player_requests_managed_mpv {
        managed_config.enabled = true;
    }

    if managed_config.mpv_bin.is_none()
        && legacy_player_requests_managed_mpv
        && let Some(player_path) = legacy_player_path
    {
        managed_config.mpv_bin = Some(PathBuf::from(player_path));
    }
    if managed_config.media_file.is_none()
        && let Some(file) = overrides.file.as_deref()
    {
        managed_config.media_file = Some(PathBuf::from(file));
    }
    if managed_config.extra_args.is_empty() && !overrides.player_args.is_empty() {
        managed_config.extra_args = overrides.player_args.clone();
    }
}

fn push_unique_pathbuf_legacy_compatible(paths: &mut Vec<PathBuf>, candidate: PathBuf) {
    if !paths.iter().any(|existing| existing == &candidate) {
        paths.push(candidate);
    }
}

#[cfg(windows)]
fn managed_mpv_launch_candidate_file_names_legacy_compatible() -> &'static [&'static str] {
    &["mpv.exe", "mpv.com"]
}

#[cfg(not(windows))]
fn managed_mpv_launch_candidate_file_names_legacy_compatible() -> &'static [&'static str] {
    &["mpv"]
}

fn resolve_managed_mpv_launch_program_legacy_compatible(requested: &Path) -> PathBuf {
    let mut candidates = vec![requested.to_path_buf()];
    if requested.is_dir() || !requested.exists() {
        for file_name in managed_mpv_launch_candidate_file_names_legacy_compatible() {
            push_unique_pathbuf_legacy_compatible(&mut candidates, requested.join(file_name));
        }
    }
    if !requested.exists()
        && let Some(parent) = requested.parent()
        && let Some(file_name) = requested.file_name().and_then(|value| value.to_str())
    {
        let normalized = file_name.trim().to_ascii_lowercase();
        if matches!(normalized.as_str(), "mpv" | "mpv.exe" | "mpv.com") {
            for candidate_file_name in managed_mpv_launch_candidate_file_names_legacy_compatible() {
                push_unique_pathbuf_legacy_compatible(
                    &mut candidates,
                    parent.join(candidate_file_name),
                );
            }
        }
    }
    candidates
        .into_iter()
        .find(|candidate| candidate.is_file())
        .unwrap_or_else(|| requested.to_path_buf())
}

fn managed_mpv_launch_program_requires_existing_file_legacy_compatible(path: &Path) -> bool {
    path.is_absolute()
        || path
            .to_string_lossy()
            .chars()
            .any(|character| matches!(character, '/' | '\\'))
}

fn legacy_player_path_requests_managed_mpv_legacy_compatible(player_path: &str) -> bool {
    let trimmed = player_path.trim();
    if trimmed.is_empty() {
        return false;
    }
    let normalized = trimmed.replace('\\', "/").to_ascii_lowercase();
    if normalized.contains("mpvnet") || !normalized.contains("mpv") {
        return false;
    }

    let file_name = Path::new(&normalized)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(normalized.as_str())
        .trim()
        .to_ascii_lowercase();
    if matches!(file_name.as_str(), "mpv" | "mpv.exe" | "mpv.com") {
        return true;
    }

    let requested = Path::new(trimmed);
    let resolved = resolve_managed_mpv_launch_program_legacy_compatible(requested);
    resolved.is_file()
        || !managed_mpv_launch_program_requires_existing_file_legacy_compatible(&resolved)
}

fn legacy_player_path_compatibility_warning_line_legacy_compatible(
    overrides: &LegacyClientArgOverrides,
) -> Option<&'static str> {
    let player_path = overrides.player_path.as_deref()?;
    if legacy_player_path_requests_managed_mpv_legacy_compatible(player_path) {
        Some(
            "warning: legacy --player-path selects managed mpv integration for Python-style mpv paths; non-mpv values remain launch-only unmanaged fallback",
        )
    } else {
        Some(
            "warning: legacy non-mpv --player-path is launch-only unmanaged fallback; it is not adapter-integrated and is ignored when managed mpv or explicit-mpv-IPC is active",
        )
    }
}

fn legacy_non_mpv_player_path_ignored_by_mpv_integration_warning_line_legacy_compatible(
    overrides: &LegacyClientArgOverrides,
) -> Option<&'static str> {
    let player_path = overrides.player_path.as_deref()?;
    if legacy_player_path_requests_managed_mpv_legacy_compatible(player_path) {
        None
    } else {
        Some(
            "warning: legacy non-mpv --player-path was ignored because managed mpv or explicit-mpv-IPC integration is active",
        )
    }
}

fn should_use_automatic_managed_mpv_for_legacy_player_path_legacy_compatible(
    legacy_overrides: Option<&LegacyClientArgOverrides>,
) -> bool {
    legacy_overrides
        .and_then(|overrides| overrides.player_path.as_deref())
        .is_some_and(legacy_player_path_requests_managed_mpv_legacy_compatible)
}

fn explicit_mpv_ipc_path_from_env() -> Option<String> {
    env_trimmed("SYNCPLAY_CLIENT_MPV_IPC_PATH").or_else(|| env_trimmed("SYNCPLAY_MPV_IPC_PATH"))
}

fn should_skip_legacy_external_player_launch_due_to_mpv_integration_env() -> bool {
    explicit_mpv_ipc_path_from_env().is_some() || managed_mpv_launch_env_config_from_env().enabled
}

fn legacy_external_player_launch_spec_from_overrides_legacy_compatible(
    overrides: &LegacyClientArgOverrides,
) -> Option<LegacyExternalPlayerLaunchSpec> {
    let program = overrides.player_path.as_deref().map(PathBuf::from)?;
    let mut args = overrides.player_args.clone();
    if let Some(file) = overrides.file.as_deref() {
        args.push(file.to_owned());
    }
    Some(LegacyExternalPlayerLaunchSpec { program, args })
}

fn parse_positive_f64_legacy_compatible(value: &str) -> Option<f64> {
    let parsed = value.trim().parse::<f64>().ok()?;
    (parsed.is_finite() && parsed > 0.0).then_some(parsed)
}

fn parse_legacy_explicit_mpv_ipc_start_position_seconds_legacy_compatible(
    value: &str,
) -> Option<f64> {
    parse_env_non_negative_f64_legacy_compatible(value)
        .or_else(|| parse_seek_time_seconds_legacy_like(value))
}

fn format_legacy_explicit_mpv_ipc_flag_and_value_token_legacy_compatible(
    flag: &str,
    value: &str,
) -> String {
    format!("{flag} {value}")
}

fn parse_legacy_explicit_mpv_ipc_generic_option_assignment_legacy_compatible(
    arg: &str,
) -> Option<(String, String)> {
    let option = arg
        .strip_prefix("--")
        .or_else(|| arg.strip_prefix('-'))
        .filter(|option| !option.is_empty())?;
    let (name, value) = option.split_once('=')?;
    let trimmed_name = name.trim();
    if trimmed_name.is_empty() {
        return None;
    }
    Some((trimmed_name.to_owned(), value.to_owned()))
}

fn legacy_explicit_mpv_ipc_startup_player_command_key_legacy_compatible(
    command: &LegacyExplicitMpvIpcStartupPlayerCommand,
) -> (&str, Option<&str>) {
    match command {
        LegacyExplicitMpvIpcStartupPlayerCommand::SetOptionString { name, .. } => {
            ("set-option", Some(name.as_str()))
        }
        LegacyExplicitMpvIpcStartupPlayerCommand::ApplyProfile { .. } => ("apply-profile", None),
    }
}

fn push_legacy_explicit_mpv_ipc_startup_player_command_legacy_compatible(
    commands: &mut Vec<LegacyExplicitMpvIpcStartupPlayerCommand>,
    command: LegacyExplicitMpvIpcStartupPlayerCommand,
) {
    let command_key =
        legacy_explicit_mpv_ipc_startup_player_command_key_legacy_compatible(&command);
    if let Some(existing_index) = commands.iter().position(|existing| {
        legacy_explicit_mpv_ipc_startup_player_command_key_legacy_compatible(existing)
            == command_key
    }) {
        commands.remove(existing_index);
    }
    commands.push(command);
}

