fn should_retry_explicit_mpv_ipc_startup_player_command_legacy_compatible(
    error: &PlayerError,
) -> bool {
    let PlayerError::OperationFailed(message) = error else {
        return false;
    };
    let lower = message.to_ascii_lowercase();
    lower.contains("property unavailable") || lower.contains("no file loaded")
}

fn retry_explicit_mpv_ipc_startup_player_command_legacy_compatible<F>(
    mut operation: F,
) -> Result<(), PlayerError>
where
    F: FnMut() -> Result<(), PlayerError>,
{
    const MAX_ATTEMPTS: usize = 20;
    const RETRY_DELAY: Duration = Duration::from_millis(25);

    let mut last_error = None;
    for attempt in 0..MAX_ATTEMPTS {
        match operation() {
            Ok(()) => return Ok(()),
            Err(error)
                if attempt + 1 < MAX_ATTEMPTS
                    && should_retry_explicit_mpv_ipc_startup_player_command_legacy_compatible(
                        &error,
                    ) =>
            {
                last_error = Some(error);
                std::thread::sleep(RETRY_DELAY);
            }
            Err(error) => return Err(error),
        }
    }
    Err(last_error.unwrap_or_else(|| {
        PlayerError::OperationFailed(
            "startup command retry unexpectedly exhausted without error".to_owned(),
        )
    }))
}

fn create_mpv_adapter_from_path_or_stub(ipc_path: &str) -> MpvAdapter {
    match MpvAdapter::with_json_ipc(ipc_path) {
        Ok(adapter) => adapter,
        Err(err) => {
            eprintln!(
                "warning: failed to connect mpv JSON IPC at '{ipc_path}': {err}; using stub mpv adapter"
            );
            MpvAdapter::default()
        }
    }
}

fn spawn_managed_mpv_and_attach(
    config: ManagedMpvLaunchEnvConfig,
) -> anyhow::Result<(MpvAdapter, ManagedMpvProcessGuard)> {
    let requested_mpv_bin = config.mpv_bin.or_else(find_default_managed_mpv_bin).ok_or_else(|| {
        anyhow!(
            "managed mpv launch requested but no mpv binary was found; set SYNCPLAY_CLIENT_MPV_MANAGED_BIN"
        )
    })?;
    let mpv_bin = resolve_managed_mpv_launch_program_legacy_compatible(&requested_mpv_bin);
    if managed_mpv_launch_program_requires_existing_file_legacy_compatible(&mpv_bin)
        && !mpv_bin.is_file()
    {
        return Err(anyhow!(
            "managed mpv binary does not exist: {}",
            mpv_bin.display()
        ));
    }
    if let Some(media_file) = config.media_file.as_ref()
        && !media_file.exists()
    {
        return Err(anyhow!(
            "managed mpv media file does not exist: {}",
            media_file.display()
        ));
    }

    let (ipc_path, ipc_cleanup_path) = if let Some(ipc_path) = config.ipc_path {
        let ipc_cleanup_path = ipc_cleanup_path_for_platform(&ipc_path);
        if let Some(path) = ipc_cleanup_path.as_ref() {
            let _ = std::fs::remove_file(path);
        }
        (ipc_path, ipc_cleanup_path)
    } else {
        generate_managed_mpv_ipc_path()?
    };

    let connect_timeout =
        Duration::from_millis(u64::from(config.connect_timeout_ms.unwrap_or(5_000).max(1)));
    let connect_poll_interval = Duration::from_millis(u64::from(
        config.connect_poll_interval_ms.unwrap_or(50).max(1),
    ));

    let mut command = Command::new(&mpv_bin);
    if let Some(parent) = mpv_bin.parent() {
        command.current_dir(parent);
    }
    command
        .arg("--pause")
        .arg("--force-window=no")
        .arg("--idle=yes")
        .arg(format!("--input-ipc-server={ipc_path}"));
    if !config.extra_args.is_empty() {
        command.args(&config.extra_args);
    }
    if let Some(media_file) = config.media_file.as_ref() {
        command.arg(media_file);
    }

    let child = command
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()?;
    let guard = ManagedMpvProcessGuard {
        child,
        ipc_cleanup_path,
    };
    let adapter = connect_mpv_adapter_with_retry(&ipc_path, connect_timeout, connect_poll_interval)
        .map_err(|err| {
            anyhow!(
                "managed mpv launched but JSON IPC attach failed (mpv_bin={}, ipc={}): {err}",
                mpv_bin.display(),
                ipc_path
            )
        })?;

    eprintln!("info: started managed mpv and attached JSON IPC at '{ipc_path}'");
    Ok((adapter, guard))
}

fn connect_mpv_adapter_with_retry(
    ipc_path: &str,
    timeout: Duration,
    poll_interval: Duration,
) -> anyhow::Result<MpvAdapter> {
    let started = std::time::Instant::now();
    let mut last_error = None;
    while started.elapsed() < timeout {
        match MpvAdapter::with_json_ipc(ipc_path) {
            Ok(adapter) => return Ok(adapter),
            Err(err) => {
                last_error = Some(err.to_string());
                std::thread::sleep(poll_interval);
            }
        }
    }

    Err(anyhow!(
        "timed out after {:?} waiting for mpv JSON IPC at '{}' (poll={:?}); last error: {}",
        timeout,
        ipc_path,
        poll_interval,
        last_error.as_deref().unwrap_or("<none>")
    ))
}

fn find_default_managed_mpv_bin() -> Option<PathBuf> {
    let cwd = std::env::current_dir().ok()?;
    for ancestor in cwd.ancestors().take(6) {
        let mpv_dir = ancestor.join("mpv");
        #[cfg(windows)]
        {
            let exe = mpv_dir.join("mpv.exe");
            if exe.exists() {
                return Some(exe);
            }
            let com = mpv_dir.join("mpv.com");
            if com.exists() {
                return Some(com);
            }
        }
        #[cfg(not(windows))]
        {
            let bin = mpv_dir.join("mpv");
            if bin.exists() {
                return Some(bin);
            }
        }
    }
    None
}

fn generate_managed_mpv_ipc_path() -> anyhow::Result<(String, Option<PathBuf>)> {
    let unique = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|err| anyhow!("system time should be after unix epoch: {err}"))?
        .as_millis();
    #[cfg(windows)]
    {
        Ok((
            format!(
                r"\\.\pipe\syncplay-rust-cli-mpv-{}-{unique}",
                std::process::id()
            ),
            None,
        ))
    }
    #[cfg(not(windows))]
    {
        let path = std::env::temp_dir().join(format!(
            "syncplay-rust-cli-mpv-{}-{unique}.sock",
            std::process::id()
        ));
        let path_str = path.to_string_lossy().into_owned();
        Ok((path_str, Some(path)))
    }
}

fn ipc_cleanup_path_for_platform(path: &str) -> Option<PathBuf> {
    #[cfg(windows)]
    {
        let _ = path;
        None
    }
    #[cfg(not(windows))]
    {
        Some(PathBuf::from(path))
    }
}

async fn write_protocol_line(
    writer: &mut tokio::net::tcp::OwnedWriteHalf,
    line: &str,
) -> anyhow::Result<()> {
    writer.write_all(line.as_bytes()).await?;
    writer.write_all(b"\n").await?;
    writer.flush().await?;
    Ok(())
}

async fn flush_runtime_protocol_lines(
    runtime: &mut ClientRuntime<MpvAdapter, QueuedRuntimeControl>,
    writer: &mut tokio::net::tcp::OwnedWriteHalf,
) -> anyhow::Result<()> {
    let mut lines = Vec::new();
    runtime.flush_queued_protocol_lines_to_transport(|line| {
        lines.push(line.to_owned());
        Ok(())
    })?;
    for line in &lines {
        write_protocol_line(writer, line).await?;
    }
    Ok(())
}

