#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let motd_template = env_trimmed("SYNCPLAY_SERVER_MOTD_TEMPLATE");
    let rooms_db_file = env_trimmed("SYNCPLAY_SERVER_ROOMS_DB_FILE");
    let permanent_rooms_file = env_trimmed("SYNCPLAY_SERVER_PERMANENT_ROOMS_FILE");
    let tls_cert_path = env_trimmed("SYNCPLAY_SERVER_TLS_CERT_PATH");
    let stats_db_file = env_trimmed("SYNCPLAY_SERVER_STATS_DB_FILE");
    let server_port = env_port("SYNCPLAY_SERVER_PORT");
    let persistent_rooms_enabled = env_flag_enabled("SYNCPLAY_SERVER_PERSISTENT_ROOMS");
    let mut server = ServerApp::new();
    if let Some(template) = motd_template {
        server.runtime_mut().set_motd_template(Some(template));
    }
    server
        .runtime_mut()
        .set_persistent_rooms_db_path(rooms_db_file.as_deref().map(std::path::PathBuf::from))?;
    server.runtime_mut().set_permanent_rooms_file_path(
        permanent_rooms_file
            .as_deref()
            .map(std::path::PathBuf::from),
    )?;
    server
        .runtime_mut()
        .set_persistent_rooms_enabled(persistent_rooms_enabled || rooms_db_file.is_some());
    if let Some(port) = server_port {
        server
            .runtime_mut()
            .set_stats_snapshot_start_delay_for_port(port);
    }
    server
        .runtime_mut()
        .set_tls_cert_path(tls_cert_path.as_deref().map(std::path::PathBuf::from));
    server
        .runtime_mut()
        .set_stats_db_path(stats_db_file.as_deref().map(std::path::PathBuf::from))?;
    server.bootstrap_room("cli-demo");

    let mut client_arg_overrides = parse_legacy_client_arg_overrides(std::env::args().skip(1));
    if client_arg_overrides.show_version {
        println!("syncplay-cli {}", env!("CARGO_PKG_VERSION"));
        return Ok(());
    }
    if client_arg_overrides.show_help {
        print_legacy_client_help(client_arg_overrides.language.as_deref());
        return Ok(());
    }
    if !client_arg_overrides.unknown_options.is_empty() {
        let unknown_options = client_arg_overrides.unknown_options.join(" ");
        eprintln!("error: unrecognized arguments: {unknown_options}");
        return Err(anyhow!("unrecognized arguments"));
    }
    if client_arg_overrides.clear_gui_data_requested {
        match clear_syncplay_cli_stored_settings_legacy_compatible() {
            Ok(true) => {
                eprintln!(
                    "cleared stored Syncplay settings (syncplay.ini) for legacy --clear-gui-data"
                );
            }
            Ok(false) => {}
            Err(error) => {
                eprintln!("warning: failed to clear stored Syncplay settings: {error}");
            }
        }
        match clear_syncplay_cli_gui_qsettings_legacy_compatible() {
            Ok(true) => {
                eprintln!("cleared legacy Syncplay GUI QSettings data for --clear-gui-data");
            }
            Ok(false) => {}
            Err(error) => {
                eprintln!("warning: failed to clear legacy Syncplay GUI QSettings: {error}");
            }
        }
    }
    if let Some(language) = client_arg_overrides.language.as_deref()
        && !client_arg_overrides.no_store
        && let Err(error) = persist_syncplay_cli_language_setting_legacy_compatible(language)
    {
        eprintln!("warning: failed to persist legacy --language setting: {error}");
    }
    if let Some(player_path) = client_arg_overrides.player_path.as_deref()
        && !client_arg_overrides.no_store
        && let Err(error) = persist_syncplay_cli_player_path_setting_legacy_compatible(player_path)
    {
        eprintln!("warning: failed to persist legacy --player-path setting: {error}");
    }
    if let Some(player_path) = client_arg_overrides.player_path.as_deref()
        && !client_arg_overrides.no_store
        && !client_arg_overrides.player_args.is_empty()
        && let Err(error) = persist_syncplay_cli_per_player_arguments_setting_legacy_compatible(
            player_path,
            &client_arg_overrides.player_args,
        )
    {
        eprintln!("warning: failed to persist legacy per-player arguments setting: {error}");
    }
    emit_legacy_client_arg_compatibility_warnings(&client_arg_overrides);
    if client_arg_overrides.should_halt_for_legacy_force_gui_prompt_compatibility() {
        return Ok(());
    }
    let stored_settings = match load_syncplay_cli_stored_settings_mvp_legacy_compatible() {
        Ok(settings) => settings,
        Err(error) => {
            eprintln!("warning: failed to load stored Syncplay settings: {error}");
            None
        }
    };
    if let Some(stored_settings) = stored_settings.as_ref() {
        if let Some(line) = stored_force_gui_prompt_compatibility_line_legacy_compatible(
            &client_arg_overrides,
            stored_settings,
        ) {
            eprintln!("{line}");
        }
        if should_halt_for_stored_force_gui_prompt_legacy_compatible(
            &client_arg_overrides,
            stored_settings,
        ) {
            return Ok(());
        }
    }
    set_legacy_runtime_language_for_process_legacy_compatible(
        resolved_legacy_runtime_language_tag_legacy_compatible(
            &client_arg_overrides,
            stored_settings.as_ref(),
        ),
    );
    apply_headless_automatic_update_check_legacy_compatible(
        &client_arg_overrides,
        stored_settings.as_ref(),
    );
    if env_flag_enabled("SYNCPLAY_CLIENT_CONNECT") || client_arg_overrides.should_connect_client() {
        let mut config = build_client_loop_config_from_env();
        if let Some(stored_settings) = stored_settings.as_ref() {
            apply_stored_client_settings_mvp_if_env_absent(&mut config, stored_settings);
            apply_stored_legacy_startup_player_defaults_if_arg_absent(
                &mut client_arg_overrides,
                stored_settings,
            );
        }
        apply_stored_media_search_startup_file_fallback_if_missing_legacy_compatible(
            &mut client_arg_overrides,
            stored_settings.as_ref(),
        );
        apply_legacy_client_arg_overrides(&mut config, &client_arg_overrides);
        if !client_arg_overrides.no_store
            && let Err(error) = persist_syncplay_cli_stored_settings_mvp_legacy_compatible(&config)
        {
            eprintln!("warning: failed to persist stored Syncplay settings: {error}");
        }
        if let Err(error) =
            spawn_legacy_external_player_if_requested_legacy_compatible(&client_arg_overrides)
        {
            eprintln!("warning: failed to launch legacy external player startup path: {error}");
        }
        run_client_network_loop_with_legacy_startup_overrides_and_stored_settings(
            &config,
            client_arg_overrides.load_playlist_from_file.as_deref(),
            Some(&client_arg_overrides),
            stored_settings.as_ref(),
        )
        .await?;
        return Ok(());
    }

    let mut client = ClientSession::default();
    client.apply_hello_json(
        r#"{"Hello":{"username":"cli-user","room":{"name":"cli-demo"},"version":"1.2.255"}}"#,
    )?;

    println!(
        "syncplay-cli bootstrap complete for user {} in room {}",
        client.username.as_deref().unwrap_or("unknown"),
        client.room.as_deref().unwrap_or("unknown")
    );
    Ok(())
}

